import React, { Component } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import MyContext from '../contexts/MyContext';
import Menu from './MenuComponent';
import Report from './ReportComponent';
import Category from './CategoryComponent';
import Product from './ProductComponent';
import Order from './OrderComponent';
import Customer from './CustomerComponent';
import Voucher from './VoucherComponent';

class Main extends Component {
  static contextType = MyContext;

  render() {
    if (this.context.token === '') return <div />;

    return (
      <div style={{ backgroundColor: '#F9F6F0', minHeight: '100vh', margin: 0, padding: 0 }}>
        {/* Menu tràn hết viền màn hình */}
        <Menu />
        
        {/* Nội dung trang bên dưới được giữ padding vừa vặn */}
        <div style={{ padding: '20px' }}>
          <Routes>
            <Route path="/admin" element={<Navigate replace to="/admin/report" />} />
            <Route path="/admin/report" element={<Report />} />
            <Route path="/admin/category" element={<Category />} />
            <Route path="/admin/product" element={<Product />} />
            <Route path="/admin/order" element={<Order />} />
            <Route path="/admin/customer" element={<Customer />} />
            <Route path="/admin/voucher" element={<Voucher />} />
            <Route path="/admin/reception" element={<Reception />} />
          </Routes>
        </div>
      </div>
    );
  }
}

export default Main;
